import Foundation
import Testing
import MLX
@testable import MLXUI

/// PF-5 — the reference fixtures for one short synthetic text (generated by PF-3's
/// `make_privacy_golden.py` from `transformers` 5.12.0): the embedding output, the hidden state after
/// each of the 8 blocks (pre final norm), the final normalized hidden state and the `[T, 33]` logits,
/// as raw little-endian `.f32` tensors.
nonisolated struct PrivacyFilterParityFixture {
    struct TensorRef {
        let file: String
        let shape: [Int]
    }

    let shortText: String
    let tokenIDs: [Int]
    let embedding: TensorRef
    let blocks: [TensorRef]
    let logits: TensorRef
    let finalNorm: TensorRef?

    static func load() throws -> PrivacyFilterParityFixture {
        let url = PrivacyFilterTestEnvironment.fixturesDirectory.appendingPathComponent("parity.json")
        guard let data = try? Data(contentsOf: url),
              let root = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
              let reference = root["reference"] as? [String: Any]
        else {
            throw PrivacyFilterTestEnvironment.FixtureError.unreadable(url.path)
        }
        guard let tokenIDs = root["tokenIds"] as? [Int] else {
            throw PrivacyFilterTestEnvironment.FixtureError.malformed("tokenIds")
        }
        func tensor(_ node: Any?) throws -> TensorRef {
            guard let dictionary = node as? [String: Any],
                  let file = dictionary["file"] as? String,
                  let shape = dictionary["shape"] as? [Int] else {
                throw PrivacyFilterTestEnvironment.FixtureError.malformed("a tensor reference")
            }
            return TensorRef(file: file, shape: shape)
        }
        guard let blocks = reference["blocks"] as? [Any], blocks.count == 8 else {
            throw PrivacyFilterTestEnvironment.FixtureError.malformed("reference.blocks")
        }
        return PrivacyFilterParityFixture(
            shortText: (root["shortText"] as? String) ?? "",
            tokenIDs: tokenIDs,
            embedding: try tensor(reference["embedding"]),
            blocks: try blocks.map(tensor),
            logits: try tensor(reference["logits"]),
            finalNorm: try (root["finalNorm"] ?? reference["finalNorm"]).map(tensor))
    }

    func floats(_ reference: TensorRef) throws -> [Float] {
        let url = PrivacyFilterTestEnvironment.fixturesDirectory.appendingPathComponent(reference.file)
        guard let data = try? Data(contentsOf: url) else {
            throw PrivacyFilterTestEnvironment.FixtureError.unreadable(reference.file)
        }
        let values = data.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
        let expected = reference.shape.reduce(1, *)
        guard values.count == expected else {
            throw PrivacyFilterTestEnvironment.FixtureError.malformed(
                "\(reference.file): \(values.count) floats, expected \(expected)")
        }
        return values
    }

    /// Maximum absolute difference between an MLX array and a raw fixture tensor.
    static func maxDifference(_ array: MLXArray, _ reference: [Float]) throws -> Float {
        let actual = try MLXErrorGuard.read(array.asType(.float32), as: Float.self)
        guard actual.count == reference.count else {
            throw PrivacyFilterTestEnvironment.FixtureError.malformed(
                "\(actual.count) values vs \(reference.count)")
        }
        var worst: Float = 0
        for (a, b) in zip(actual, reference) { worst = max(worst, abs(a - b)) }
        return worst
    }

    static func maximumMagnitude(_ reference: [Float]) -> Float {
        reference.reduce(0) { max($0, abs($1)) }
    }

    /// Distribution metrics for one stage: absolute max, RMS of the difference, RMS relative to the
    /// reference's RMS (the residual stream grows ~3x per block, so absolute max alone is not a
    /// meaningful bound), Pearson correlation, and the fraction of elements differing by > 0.1.
    static func distribution(_ actual: [Float], _ reference: [Float])
        -> (max: Float, rms: Double, relativeRms: Double, pearson: Double, fractionOver: Double)
    {
        guard actual.count == reference.count, !actual.isEmpty else {
            return (.infinity, .infinity, .infinity, .nan, 1)
        }
        var worst: Float = 0
        var sumSquared = 0.0
        var referenceSquared = 0.0
        var over = 0
        for (a, b) in zip(actual, reference) {
            let delta = abs(a - b)
            worst = max(worst, delta)
            sumSquared += Double(delta) * Double(delta)
            referenceSquared += Double(b) * Double(b)
            if delta > 0.1 { over += 1 }
        }
        let count = Double(actual.count)
        let rms = (sumSquared / count).squareRoot()
        let referenceRms = (referenceSquared / count).squareRoot()
        return (
            worst, rms, referenceRms > 0 ? rms / referenceRms : .infinity,
            pearson(actual, reference), Double(over) / count)
    }

    /// Pearson correlation over every element (the issue's `r >= 0.999` for the logits).
    static func pearson(_ actual: [Float], _ reference: [Float]) -> Double {
        guard actual.count == reference.count, !actual.isEmpty else { return .nan }
        var sumA = 0.0, sumB = 0.0
        for (a, b) in zip(actual, reference) { sumA += Double(a); sumB += Double(b) }
        let meanA = sumA / Double(actual.count)
        let meanB = sumB / Double(reference.count)
        var covariance = 0.0, varianceA = 0.0, varianceB = 0.0
        for (a, b) in zip(actual, reference) {
            let da = Double(a) - meanA
            let db = Double(b) - meanB
            covariance += da * db
            varianceA += da * da
            varianceB += db * db
        }
        guard varianceA > 0, varianceB > 0 else { return .nan }
        return covariance / (varianceA.squareRoot() * varianceB.squareRoot())
    }
}

extension PrivacyFilterTestEnvironment {
    nonisolated enum FixtureError: Error, CustomStringConvertible {
        case unreadable(String)
        case malformed(String)
        var description: String {
            switch self {
            case .unreadable(let path): return "the fixture \(path) could not be read"
            case .malformed(let detail): return "the parity fixture is malformed: \(detail)"
            }
        }
    }
}

/// PF-5 — parity against the pinned `transformers` 5.12.0 reference on real weights.
///
/// Gated exactly like `SAMAudioRealLoadTests`: `MLXUI_TEST_PRIVACY=1` (reached as
/// `TEST_RUNNER_MLXUI_TEST_PRIVACY=1`) **and** `MLXUI_TEST_PRIVACY_DIR` pointing at an installed copy
/// (normally `/private/tmp/pf-model`). A skipped run is not evidence.
///
/// The bounds are the band of the reference-to-reference controls measured on this same probe
/// (`/tmp/pf-team/parity-controls.json`): **A** = opf's own original PyTorch implementation, bf16, vs
/// the stored transformers-bf16 fixtures; **B** = transformers fp32 (upcast) vs transformers bf16.
/// Two correct bf16 implementations cannot agree much more closely than A and B do — the residual
/// stream grows ~3x per layer (absmax 330 -> 18,688) and the discrete top-4 router turns a bf16
/// near-tie into a multi-unit change on one row (Trap 4) — so the acceptance is Pearson floors plus a
/// relative-RMS ceiling, not an absolute max on an 18k-scale stream. Measured numbers are printed by
/// every run and recorded in the PR.
@Suite(.serialized)
struct PrivacyFilterNetworkParityTests {

    /// Embedding is a table lookup, so it must be bit-identical.
    static let embeddingTolerance: Float = 0

    // Control floors on this probe: logits r 0.999597 (A) / 0.999844 (B), max|Δ| 1.75 (A) / 0.629 (B);
    // per-block r (A) [1.0, .999999, .999963, .999860, .999659, .999798, .999773, .999773],
    // (B) [.999978, .999941, .999966, .999946, .999971, .999930, .999878, .999901];
    // final norm r 0.999056 (A) / 0.999691 (B), max|Δ| 3.0 (A) / 2.1475 (B).
    // Measured for this port: logits r 0.999754 max|Δ| 1.203; worst block r 0.999818 and worst
    // relative RMS 1.91% (both block 4); final norm r 0.999272 max|Δ| 3.0.

    /// Per-block Pearson floor. Measured worst 0.999818; control A's worst 0.999659.
    static let blockPearsonFloor = 0.9995
    /// Per-block RMS(Δ) / RMS(reference) ceiling. Measured worst 1.91%; control A's range is ~0.4-2.6%.
    static let blockRelativeRmsCeiling = 0.03

    /// Final norm: max |Δ| (measured 3.0; control A 3.0) and Pearson floor (measured 0.999272).
    static let finalNormTolerance: Float = 4.0
    static let finalNormPearsonFloor = 0.999

    /// Final `[T, 33]` logits: the issue asks `r >= 0.999`; this port measures 0.999754, between the
    /// two control floors, so the floor is control A's. Max |Δ| measured 1.203 (A 1.75, B 0.629).
    static let logitsPearsonFloor = 0.9995
    static let logitsTolerance: Float = 2.0

    private static var enabled: Bool { PrivacyFilterTestEnvironment.canRun }

    @Test(.enabled(if: PrivacyFilterNetworkParityTests.enabled))
    func theShortTextMatchesTheReferenceLayerByLayer() throws {
        let directory = try #require(PrivacyFilterTestEnvironment.directory)
        let fixture = try PrivacyFilterParityFixture.load()
        Memory.clearCache()
        Memory.peakMemory = 0
        MLXErrorGuard.installFallback()
        MLXErrorGuard.resetFallbackMessage()

        let started = Date()
        let model = try PrivacyFilterModel.load(from: directory)
        let loaded = Date().timeIntervalSince(started)
        print("PFPARITY tokens=\(fixture.tokenIDs.count) loadWall=\(String(format: "%.1f", loaded)) s")

        let startedForward = Date()
        let trace = model.trace(tokenIDs: fixture.tokenIDs)
        let wall = Date().timeIntervalSince(startedForward)

        #expect(trace.blocks.count == 8, "one hidden state per block")
        #expect(trace.logits.shape == [fixture.tokenIDs.count, 33], "logits are [T, 33]")

        // 1. Embedding must be exact (a lookup, no arithmetic).
        let embeddingReference = try fixture.floats(fixture.embedding)
        let embeddingDelta = try PrivacyFilterParityFixture.maxDifference(trace.embedding, embeddingReference)
        print(String(format: "PFPARITY stage=embedding maxDelta=%g tol=%g", embeddingDelta, Self.embeddingTolerance))
        #expect(embeddingDelta <= Self.embeddingTolerance, "the embedding is a lookup and must match exactly")

        // 2. Each block's hidden state. The residual stream grows ~3x per block (absmax 330 at
        //    block 0 -> 18,688 at block 7), so the meaningful numbers are the relative RMS, Pearson
        //    and the fraction of elements that move — the absolute max is reported for the record.
        var worstBlockDelta: Float = 0
        var worstBlockRelativeRms: Double = 0
        var worstBlockPearson: Double = 1
        for (index, reference) in fixture.blocks.enumerated() {
            let values = try fixture.floats(reference)
            let actual = try MLXErrorGuard.read(trace.blocks[index].asType(.float32), as: Float.self)
            let stats = PrivacyFilterParityFixture.distribution(actual, values)
            let magnitude = PrivacyFilterParityFixture.maximumMagnitude(values)
            worstBlockDelta = max(worstBlockDelta, stats.max)
            worstBlockRelativeRms = max(worstBlockRelativeRms, stats.relativeRms)
            worstBlockPearson = min(worstBlockPearson, stats.pearson)
            print(String(format:
                "PFPARITY stage=block%d maxDelta=%g maxAbs=%.1f rmsDelta=%.4f relRms=%.5f pearson=%.6f fracOver0.1=%.5f relRmsCeiling=%g",
                index, stats.max, magnitude, stats.rms, stats.relativeRms, stats.pearson,
                stats.fractionOver, Self.blockRelativeRmsCeiling))
            #expect(stats.pearson >= Self.blockPearsonFloor,
                    Comment(rawValue: "block \(index) Pearson \(stats.pearson) below the control floor"))
            #expect(stats.relativeRms <= Self.blockRelativeRmsCeiling,
                    Comment(rawValue: "block \(index) relative RMS \(stats.relativeRms) above the control band"))
        }

        // 3. The final RMSNorm on top of the last block (the reference stores it separately because
        //    `last_hidden_state` is post-norm, while blocks[7] is pre-norm).
        if let finalNorm = fixture.finalNorm {
            let normalized = PrivacyFilterNetwork.rmsNorm(
                trace.blocks[7], weight: model.weights.norm, eps: model.config.rmsNormEps)
            let values = try fixture.floats(finalNorm)
            let actual = try MLXErrorGuard.read(normalized.asType(.float32), as: Float.self)
            let stats = PrivacyFilterParityFixture.distribution(actual, values)
            print(String(format:
                "PFPARITY stage=finalNorm maxDelta=%g rmsDelta=%.4f relRms=%.5f pearson=%.6f fracOver0.1=%.5f tol=%g",
                stats.max, stats.rms, stats.relativeRms, stats.pearson, stats.fractionOver,
                Self.finalNormTolerance))
            #expect(stats.max <= Self.finalNormTolerance,
                    Comment(rawValue: "the final norm drifted by \(stats.max)"))
            #expect(stats.pearson >= Self.finalNormPearsonFloor,
                    Comment(rawValue: "the final norm Pearson \(stats.pearson) below the control floor"))
        }

        // 4. The final logits: Pearson r and max |Δ|.
        let logitsReference = try fixture.floats(fixture.logits)
        let logits = try MLXErrorGuard.read(trace.logits.asType(.float32), as: Float.self)
        let logitsDelta = try PrivacyFilterParityFixture.maxDifference(trace.logits, logitsReference)
        let correlation = PrivacyFilterParityFixture.pearson(logits, logitsReference)
        let logitsStats = PrivacyFilterParityFixture.distribution(logits, logitsReference)
        print(String(format:
            "PFPARITY stage=logits pearson=%.6f maxDelta=%g rmsDelta=%.4f relRms=%.5f fracOver0.1=%.5f tol=%g forwardWall=%.2f s peakMemoryGB=%.2f fallback=%@",
            correlation, logitsDelta, logitsStats.rms, logitsStats.relativeRms,
            logitsStats.fractionOver, Self.logitsTolerance, wall,
            Double(Memory.snapshot().peakMemory) / 1e9,
            MLXErrorGuard.lastFallbackMessage() ?? "none"))
        #expect(correlation >= Self.logitsPearsonFloor,
                Comment(rawValue: "the logits Pearson \(correlation) is below the reference-control floor"))
        #expect(logitsDelta <= Self.logitsTolerance, Comment(rawValue: "the logits drifted by \(logitsDelta)"))
        print(String(format:
            "PFPARITY summary worstBlockDelta=%g worstBlockRelRms=%.5f worstBlockPearson=%.6f",
            worstBlockDelta, worstBlockRelativeRms, worstBlockPearson))
        #expect(MLXErrorGuard.lastFallbackMessage() == nil, "no MLX error may be recorded during the forward pass")
    }

    /// The read-back path: `logProbs` is the fp32 log-softmax of the same logits, so it must match the
    /// fixture's logits run through `log_softmax` (the decoder's actual input).
    @Test(.enabled(if: PrivacyFilterNetworkParityTests.enabled))
    func logProbsMatchTheReferenceLogSoftmax() throws {
        let directory = try #require(PrivacyFilterTestEnvironment.directory)
        let fixture = try PrivacyFilterParityFixture.load()
        let model = try PrivacyFilterModel.load(from: directory)
        let logitsReference = try fixture.floats(fixture.logits)
        let labels = model.config.numLabels
        let rows = fixture.tokenIDs.count

        var expected: [Float] = []
        expected.reserveCapacity(rows * labels)
        for row in 0 ..< rows {
            let start = row * labels
            let slice = Array(logitsReference[start ..< (start + labels)])
            let maximum = slice.max() ?? 0
            let denominator = slice.map { exp(Double($0 - maximum)) }.reduce(0, +)
            expected.append(contentsOf: slice.map { $0 - maximum - Float(log(denominator)) })
        }

        let logProbs = try model.logProbs(tokenIDs: fixture.tokenIDs)
        let flat = logProbs.flatMap { $0 }
        #expect(flat.count == expected.count)
        var worst: Float = 0
        for (a, b) in zip(flat, expected) { worst = max(worst, abs(a - b)) }
        let correlation = PrivacyFilterParityFixture.pearson(flat, expected)
        print(String(format: "PFPARITY stage=logProbs pearson=%.6f maxDelta=%g", correlation, worst))
        #expect(correlation >= 0.999, Comment(rawValue: "logProbs must follow the reference log-softmax (\(correlation))"))
        #expect(worst <= 2.0, Comment(rawValue: "logProbs drifted by \(worst) (logit max |Δ| plus the log-softmax shift)"))
    }

    /// Trap 7: MLX arrays are read on the thread that built them, and reading after a failed `eval`
    /// crashes. Running the whole forward **on the main actor** must still produce readable arrays, and
    /// a failed evaluation must surface as a thrown error from `logProbs`, never as a read.
    @MainActor
    @Test(.enabled(if: PrivacyFilterNetworkParityTests.enabled))
    func theMainActorForwardPassReturnsReadableArrays() throws {
        let directory = try #require(PrivacyFilterTestEnvironment.directory)
        let fixture = try PrivacyFilterParityFixture.load()
        MLXErrorGuard.installFallback()
        MLXErrorGuard.resetFallbackMessage()
        let model = try PrivacyFilterModel.load(from: directory)

        let logits = model.logits(tokenIDs: fixture.tokenIDs)
        let values = try MLXErrorGuard.read(logits.asType(.float32), as: Float.self)
        #expect(values.count == fixture.tokenIDs.count * 33)
        #expect(values.allSatisfy { $0.isFinite })
        let logProbs = try model.logProbs(tokenIDs: fixture.tokenIDs)
        #expect(logProbs.count == fixture.tokenIDs.count)
        #expect(logProbs.allSatisfy { $0.allSatisfy { $0.isFinite } })
        #expect(MLXErrorGuard.lastFallbackMessage() == nil)

        // A failed evaluation is thrown, not read: inject one failure at the read site and require a
        // thrown error (the model's arrays are discarded unread).
        MLXErrorGuard.injectFailureForTesting("injected MLX failure (PF-5 parity test)")
        defer {
            MLXErrorGuard.clearInjectedFailureForTesting()
            MLXErrorGuard.resetFallbackMessage()
        }
        do {
            _ = try model.logProbs(tokenIDs: fixture.tokenIDs)
            Issue.record("a failed evaluation must not be read back as log-probs")
        } catch {
            #expect(MLXErrorGuard.injectedFailureWasConsumedForTesting(),
                    "the failure must be consumed at the guarded read site")
        }
    }

    /// Control for PF-6's windowed-vs-full-mask comparison (decode's long-input check, 6019 tokens):
    /// the same model called on a **longer** sequence vs a prefix of it must give the same rows for
    /// the shared positions. If a few rows still move, the residual is shape-dependent GEMM kernel
    /// numerics amplified by the discrete top-4 router — not windowing. No input text is involved:
    /// the ids are a synthetic deterministic sequence (metadata only, decision 10).
    @Test(.enabled(if: PrivacyFilterNetworkParityTests.enabled))
    func callLengthItselfMovesOnlyAFewRows() throws {
        let directory = try #require(PrivacyFilterTestEnvironment.directory)
        MLXErrorGuard.installFallback()
        MLXErrorGuard.resetFallbackMessage()
        let model = try PrivacyFilterModel.load(from: directory)
        let prefixCount = 4096
        let ids = (0 ..< 6019).map { ($0 &* 7919 &+ 104_729) % model.config.vocabSize }

        let started = Date()
        let full = try model.logProbs(tokenIDs: ids)
        let prefix = try model.logProbs(tokenIDs: Array(ids.prefix(prefixCount)))
        let wall = Date().timeIntervalSince(started)

        var worst: Float = 0
        var worstRow = 0
        var rowsOver01 = 0, rowsOver05 = 0, rowsOver1 = 0
        for row in 0 ..< prefixCount {
            var rowWorst: Float = 0
            for (a, b) in zip(prefix[row], full[row]) { rowWorst = max(rowWorst, abs(a - b)) }
            if rowWorst > 0.1 { rowsOver01 += 1 }
            if rowWorst > 0.5 { rowsOver05 += 1 }
            if rowWorst > 1.0 { rowsOver1 += 1 }
            if rowWorst > worst { worst = rowWorst; worstRow = row }
        }
        let correlation = PrivacyFilterParityFixture.pearson(
            prefix.flatMap { $0 }, full.prefix(prefixCount).flatMap { $0 })
        print(String(format:
            "PFCONTROL rows=%d maxDelta=%g worstRow=%d rowsOver0.1=%d rowsOver0.5=%d rowsOver1.0=%d pearson=%.6f wall=%.1f s",
            prefixCount, worst, worstRow, rowsOver01, rowsOver05, rowsOver1, correlation, wall))
        // Same model, same positions, different CALL LENGTH only — the control for PF-6's
        // windowed-vs-full comparison. Measured: r=0.993017, 6.1% of rows move by > 1 log-prob unit,
        // i.e. the length-only effect is larger than the windowed effect (decode measures 92% of
        // windowed rows within 0.05). The test's purpose is to keep this number visible, not to
        // demand zero: no windowing code is involved in this comparison at all.
        #expect(correlation > 0.99, "two call lengths must agree in aggregate")
        #expect(rowsOver1 < prefixCount / 10, "no more than 10% of rows may move by > 1 log-prob unit")
        #expect(MLXErrorGuard.lastFallbackMessage() == nil, "no MLX error may be recorded")
    }
}
